class Solution {
public:
    vector<int> closestRoom(vector<vector<int>>& rooms, vector<vector<int>>& queries) {
        sort(rooms.begin(), rooms.end(), [](const auto& a, const auto& b) {
            return a[1] > b[1];
        });

        int q = queries.size();
        vector<vector<int>> iq(q);
        for (int i = 0; i < q; ++i) {
            iq[i] = {queries[i][1], queries[i][0], i};
        }
        sort(iq.begin(), iq.end(), [](const auto& a, const auto& b) {
            return a[0] > b[0];
        });

        set<int> active;
        vector<int> ans(q, -1);
        int roomIdx = 0, n = rooms.size();

        for (const auto& query : iq) {
            int minSz = query[0], pref = query[1], qIdx = query[2];
            while (roomIdx < n && rooms[roomIdx][1] >= minSz) {
                active.insert(rooms[roomIdx][0]);
                roomIdx++;
            }
            if (active.empty()) continue;

            auto it = active.lower_bound(pref);
            int bestId = -1, minDist = 1e9;
            if (it != active.end()) {
                minDist = *it - pref;
                bestId = *it;
            }
            if (it != active.begin()) {
                auto prevIt = prev(it);
                int distLeft = pref - *prevIt;
                if (distLeft <= minDist) {
                    bestId = *prevIt;
                }
            }
            ans[qIdx] = bestId;
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int[] closestRoom(int[][] rooms, int[][] queries) {
        Arrays.sort(rooms, (a, b) -> Integer.compare(b[1], a[1]));
        int q = queries.length;
        int[][] iq = new int[q][3];
        for (int i = 0; i < q; ++i) {
            iq[i] = new int[]{queries[i][1], queries[i][0], i};
        }
        Arrays.sort(iq, (a, b) -> Integer.compare(b[0], a[0]));

        TreeSet<Integer> active = new TreeSet<>();
        int[] ans = new int[q];
        Arrays.fill(ans, -1);
        int roomIdx = 0, n = rooms.length;

        for (int[] query : iq) {
            int minSz = query[0], pref = query[1], qIdx = query[2];
            while (roomIdx < n && rooms[roomIdx][1] >= minSz) {
                active.add(rooms[roomIdx][0]);
                roomIdx++;
            }
            if (active.isEmpty()) continue;

            Integer floor = active.floor(pref);
            Integer ceil = active.ceiling(pref);
            int bestId = -1;
            int minDist = Integer.MAX_VALUE;

            if (ceil != null) {
                minDist = ceil - pref;
                bestId = ceil;
            }
            if (floor != null) {
                int distLeft = pref - floor;
                if (distLeft <= minDist) {
                    bestId = floor;
                }
            }
            ans[qIdx] = bestId;
        }
        return ans;
    }
}

/**
 * @param {number[][]} rooms
 * @param {number[][]} queries
 * @return {number[]}
 */
var closestRoom = function(rooms, queries) {
    rooms.sort((a, b) => b[1] - a[1]);
    const q = queries.length;
    const iq = queries.map((query, i) => [query[1], query[0], i]);
    iq.sort((a, b) => b[0] - a[0]);

    const active = [];
    const ans = Array(q).fill(-1);
    let roomIdx = 0, n = rooms.length;

    const insort = (val) => {
        let low = 0, high = active.length;
        while (low < high) {
            const mid = Math.floor((low + high) / 2);
            if (active[mid] < val) low = mid + 1;
            else high = mid;
        }
        active.splice(low, 0, val);
    };

    const bisectLeft = (val) => {
        let low = 0, high = active.length;
        while (low < high) {
            const mid = Math.floor((low + high) / 2);
            if (active[mid] < val) low = mid + 1;
            else high = mid;
        }
        return low;
    };

    for (const [minSz, pref, qIdx] of iq) {
        while (roomIdx < n && rooms[roomIdx][1] >= minSz) {
            insort(rooms[roomIdx][0]);
            roomIdx++;
        }
        if (active.length === 0) continue;

        const idx = bisectLeft(pref);
        let bestId = -1, minDist = Infinity;
        if (idx < active.length) {
            minDist = active[idx] - pref;
            bestId = active[idx];
        }
        if (idx > 0) {
            const distLeft = pref - active[idx - 1];
            if (distLeft <= minDist) {
                bestId = active[idx - 1];
            }
        }
        ans[qIdx] = bestId;
    }
    return ans;
};
